(6177944, 911943, 30364, '<td valign="top">Yes.  That''s exactly right in every way.  Thanks.</td>', 'Yes.  That''s exactly right in every way.  Thanks.', '2010-10-02 02:38:48.000000', NULL, 1),
(6177948, 911240, 30364, '<td valign="top">very fine image.  thanks.</td>', 'very fine image.  thanks.', '2010-10-02 02:41:50.000000', NULL, 1),
(6177949, 910787, 30364, '<td valign="top">very well conceived and executed portrait.</td>', 'very well conceived and executed portrait.', '2010-10-02 02:41:59.000000', NULL, 1),
(6177950, 911609, 30364, '<td valign="top">yep.  i do like this.</td>', 'yep.  i do like this.', '2010-10-02 02:42:46.000000', NULL, 1),
(6177953, 912150, 30364, '<td valign="top">Very lovely.  Recalls Harry Gruyaert''s beautiful <a href="//www.magnumphotos.com/Archive/c.aspx?VP=XSpecific_MAG.StoryDetail_VPage&amp;pid=2TYRYDDWUYMQ" rel="nofollow" target="_blank">Rivages</a></td>', 'Very lovely.  Recalls Harry Gruyaert''s beautiful Rivages', '2010-10-02 02:45:25.000000', NULL, 1),
(6177956, 910787, 108580, '<td valign="top">How fortunate you are to photograph this fantastic and accomplished singer. I like the single light above his head and the ambient lighting from his right gives form and depth. I might have moved the chair to be 100% under the overhead light. You have captured an intrepid expectational look on his face, with a touch of humour. The shadows being cast also break up the plain carpet. The curtain just seems to me to be out of place, but the curved wall adds a less harsh dimension than a traditional 90 degree corner.</td>', 'How fortunate you are to photograph this fantastic and accomplished singer. I like the single light above his head and the ambient lighting from his right gives form and depth. I might have moved the chair to be 100% under the overhead light. You have captured an intrepid expectational look on his face, with a touch of humour. The shadows being cast also break up the plain carpet. The curtain just seems to me to be out of place, but the curved wall adds a less harsh dimension than a traditional 90 degree corner.', '2010-10-02 02:50:09.000000', NULL, 1),
(6177959, 909533, 108580, '<td valign="top">Fantastic shot of an amazing test of pilot skill. This isn''t easy to shoot and I''d like to know what your technique and gear was. Not to copy you, just for my own interest sake as I too shot at <a href="//www.flickr.com/photos/magnum_za/sets/72157624611208035/" rel="nofollow" target="_blank">airshows</a>.</td>', 'Fantastic shot of an amazing test of pilot skill. This isn''t easy to shoot and I''d like to know what your technique and gear was. Not to copy you, just for my own interest sake as I too shot at airshows.', '2010-10-02 02:54:50.000000', NULL, 1);
