(6178262, 911491, 96751, '<td valign="top">This looks like a fantasy.  Such incredibly pleasing lines in the trees.</td>', 'This looks like a fantasy.  Such incredibly pleasing lines in the trees.', '2010-10-02 15:16:51.000000', NULL, 1),
(6178264, 911919, 96751, '<td valign="top">Great bw conversion.  Rich tonal range and pleasing elements, although just a bit static and crowded for my taste.</td>', 'Great bw conversion.  Rich tonal range and pleasing elements, although just a bit static and crowded for my taste.', '2010-10-02 15:17:23.000000', NULL, 1),
(6178265, 912175, 96751, '<td valign="top">Although the pp is not to my taste, this is an beautiful scene.  I love taking pictures from the air.  The cloud shadows are an extra goody.</td>', 'Although the pp is not to my taste, this is an beautiful scene.  I love taking pictures from the air.  The cloud shadows are an extra goody.', '2010-10-02 15:18:14.000000', NULL, 1),
(6178266, 911871, 96751, '<td valign="top">That shadow is amazing, especially the hair!  Caught at the perfect instant.</td>', 'That shadow is amazing, especially the hair!  Caught at the perfect instant.', '2010-10-02 15:19:10.000000', NULL, 1),
(6178267, 911847, 92577, '<td valign="top">stunning (See you soon in Macro Vll)</td>', 'stunning (See you soon in Macro Vll)', '2010-10-02 15:19:37.000000', NULL, 1),
(6178268, 910157, 96751, '<td valign="top">I love me some fog!!!  Iconic beach-in-the-fog image, but it''s the gulls that make the picture for me.  The diagonal like of the water is great, although I would crop out the right side to the standing rock, and a bit off the negative space on the top to better concentrate and balance the rest of the goodies.</td>', 'I love me some fog!!!  Iconic beach-in-the-fog image, but it''s the gulls that make the picture for me.  The diagonal like of the water is great, although I would crop out the right side to the standing rock, and a bit off the negative space on the top to better concentrate and balance the rest of the goodies.', '2010-10-02 15:22:33.000000', NULL, 1),
(6178269, 910113, 96751, '<td valign="top">Freaky!</td>', 'Freaky!', '2010-10-02 15:23:11.000000', NULL, 1),
(6178271, 912027, 96751, '<td valign="top">Outtakes, huh?  So much to look at here.  In fact, too much.  I am finding that negative images tend to bring out an incredible amount of detail, and for me, the amount of detail here is overwhelming.</td>', 'Outtakes, huh?  So much to look at here.  In fact, too much.  I am finding that negative images tend to bring out an incredible amount of detail, and for me, the amount of detail here is overwhelming.', '2010-10-02 15:24:19.000000', NULL, 1),
(6178272, 909831, 96751, '<td valign="top">Great use of motion blur.  Based on content, I''d have to guess <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30214" rel="nofollow" target="_blank">LevT</a>???  If so, when are we going to tango :-)</td>', 'Great use of motion blur.  Based on content, I''d have to guess  LevT???  If so, when are we going to tango :-)', '2010-10-02 15:25:29.000000', NULL, 1),
(6178273, 912146, 96751, '<td valign="top">Stunning, and just one notch too sharpened.</td>', 'Stunning, and just one notch too sharpened.', '2010-10-02 15:26:00.000000', NULL, 1),
(6178274, 912095, 96751, '<td valign="top">OMG!!! This is fantastic!!!!  Such an unusual take on a popular subject.  Simply awesome.  And the choice of b/w is brilliant.  Like moths drawn to the flame, or abductees drawn to the mother ship...  The creases on the balloon are just melting my heart.</td>', 'OMG!!! This is fantastic!!!!  Such an unusual take on a popular subject.  Simply awesome.  And the choice of b/w is brilliant.  Like moths drawn to the flame, or abductees drawn to the mother ship...  The creases on the balloon are just melting my heart.', '2010-10-02 15:27:38.000000', NULL, 1),
(6178275, 909961, 96751, '<td valign="top">Terrific lighting.  But there is something in the processing (which I also get, and don''t know how to fix), which creates blotchy patches of color in an unattractive manner - especially on the face.</td>', 'Terrific lighting.  But there is something in the processing (which I also get, and don''t know how to fix), which creates blotchy patches of color in an unattractive manner - especially on the face.', '2010-10-02 15:29:06.000000', NULL, 1),
