(6178280, 912111, 96751, '<td valign="top">Great elements for a strong abstract, which I see in b/w...</td>', 'Great elements for a strong abstract, which I see in b/w...', '2010-10-02 15:34:20.000000', NULL, 1),
(6178285, 911900, 96751, '<td valign="top">The lighting here is splendid, but it seems a bit unfocused.</td>', 'The lighting here is splendid, but it seems a bit unfocused.', '2010-10-02 15:38:25.000000', NULL, 1),
(6178287, 909828, 96751, '<td valign="top">Fabulous found filter.</td>', 'Fabulous found filter.', '2010-10-02 15:38:46.000000', NULL, 1),
