(6178291, 909866, 96751, '<td valign="top">Very nice architectural.  Maybe a little bit of dodging on the tree to reduce the amount of contrast between it and the top portion of the image.</td>', 'Very nice architectural.  Maybe a little bit of dodging on the tree to reduce the amount of contrast between it and the top portion of the image.', '2010-10-02 15:41:16.000000', NULL, 1),
(6178292, 911986, 96751, '<td valign="top">So much implied here.  Though probably not most DPCers cup of tea, there is a fervent little handful of us that really enjoy this sort of art :-)</td>', 'So much implied here.  Though probably not most DPCers cup of tea, there is a fervent little handful of us that really enjoy this sort of art :-)', '2010-10-02 15:42:26.000000', NULL, 1),
