(6178441, 909700, 91783, '<td valign="top">i love it! the colors are great!</td>', 'i love it! the colors are great!', '2010-10-02 17:33:00.000000', NULL, 1),
(6178531, 910320, 75618, '<td valign="top">I''m guessing this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=99710" rel="nofollow" target="_blank">denbote</a>. I like this so much more than the similar "depressing/gloomy" shots of children in the slums because it doesn''t appear contrived and "exploitative." Growing up in such an area, I know personally that people there still manage to find some happiness regardless of their "poor" living conditions. What I find interesting is that suicide rates in these areas are significantly lower than in places that are supposed to have a good quality of living... but anyway back to the picture, it''s very well composed. I love the contrast between the harsh environment and the overall happy vibe of the image. 9</td>', 'I''m guessing this is  denbote. I like this so much more than the similar "depressing/gloomy" shots of children in the slums because it doesn''t appear contrived and "exploitative." Growing up in such an area, I know personally that people there still manage to find some happiness regardless of their "poor" living conditions. What I find interesting is that suicide rates in these areas are significantly lower than in places that are supposed to have a good quality of living... but anyway back to the picture, it''s very well composed. I love the contrast between the harsh environment and the overall happy vibe of the image. 9', '2010-10-02 19:32:26.000000', NULL, 1),
(6178534, 912166, 75618, '<td valign="top">Wonderful! Interesting shapes and textures. 9</td>', 'Wonderful! Interesting shapes and textures. 9', '2010-10-02 19:37:59.000000', NULL, 1),
