(6180474, 909931, 33361, '<td valign="top">Sweeeet!</td>', 'Sweeeet!', '2010-10-04 09:37:27.000000', NULL, 1),
(6180480, 909533, 33361, '<td valign="top">I can''t wait til the challenge is over to find out how you did this. Is this formation flying? And if so, it''s amazingly sharp, so I think probably not. Is it a model airplane? Possibly - makes more sense as to getting this to be so sharp. Is it an illegal PS trick? Time will tell... : )</td>', 'I can''t wait til the challenge is over to find out how you did this. Is this formation flying? And if so, it''s amazingly sharp, so I think probably not. Is it a model airplane? Possibly - makes more sense as to getting this to be so sharp. Is it an illegal PS trick? Time will tell... : )', '2010-10-04 09:40:03.000000', NULL, 1),
(6180481, 911774, 33361, '<td valign="top">Lovely color and long exposure!!</td>', 'Lovely color and long exposure!!', '2010-10-04 09:40:43.000000', NULL, 1),
(6180486, 911909, 33361, '<td valign="top">This is such a dreamy place!! I think of Lemuria or Atlantis when I see it.</td>', 'This is such a dreamy place!! I think of Lemuria or Atlantis when I see it.', '2010-10-04 09:42:34.000000', NULL, 1),
(6180487, 907596, 33361, '<td valign="top">Awesome!!</td>', 'Awesome!!', '2010-10-04 09:42:52.000000', NULL, 1),
(6180489, 910332, 33361, '<td valign="top">love the tones and shadows.</td>', 'love the tones and shadows.', '2010-10-04 09:43:21.000000', NULL, 1),
(6180612, 912169, 60495, '<td valign="top">The colors are beautiful but the crop just seems awkward to me, I really like the praying mantis and IMO maybe a little less foreground to get more attention on him may have worked better. 6</td>', 'The colors are beautiful but the crop just seems awkward to me, I really like the praying mantis and IMO maybe a little less foreground to get more attention on him may have worked better. 6', '2010-10-04 11:36:01.000000', NULL, 1),
(6180629, 909885, 60495, '<td valign="top">Beautiful scene and subject, the framing IMO is way to tight on the head and the feet are cut off which really affects how well the shot works. I also am not a big fan of skies that have been pushed a little to far in PP. With a few tweaks this could have been an even better image. Good luck in the challenge.</td>', 'Beautiful scene and subject, the framing IMO is way to tight on the head and the feet are cut off which really affects how well the shot works. I also am not a big fan of skies that have been pushed a little to far in PP. With a few tweaks this could have been an even better image. Good luck in the challenge.', '2010-10-04 11:43:58.000000', NULL, 1),
(6180630, 911997, 113419, '<td valign="top">good image - personally woulda like it better had the boy in the foreground been cropped out</td>', 'good image - personally woulda like it better had the boy in the foreground been cropped out', '2010-10-04 11:44:45.000000', NULL, 1),
(6180632, 909859, 113419, '<td valign="top">very pretty image</td>', 'very pretty image', '2010-10-04 11:46:18.000000', NULL, 1),
