(6183910, 909456, 112798, '<td valign="top">I think I would have liked it better if the post/beam on the left side were parallel to the frame, but what a cool subject!</td>', 'I think I would have liked it better if the post/beam on the left side were parallel to the frame, but what a cool subject!', '2010-10-06 20:14:23.000000', NULL, 1),
(6183912, 912254, 76335, '<td valign="top">I''m glad you didn''t clean up the noise. I think any attempt to would have obliterated all the fine textures in the image.</td>', 'I''m glad you didn''t clean up the noise. I think any attempt to would have obliterated all the fine textures in the image.', '2010-10-06 20:15:31.000000', NULL, 1),
(6183913, 909747, 112798, '<td valign="top">Niiice composition...I probably would have cropped a bit of the bottom space out.</td>', 'Niiice composition...I probably would have cropped a bit of the bottom space out.', '2010-10-06 20:15:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6183916, 910356, 76335, '<td valign="top">A flash in the bathroom? Fun stuff!</td>', 'A flash in the bathroom? Fun stuff!', '2010-10-06 20:18:03.000000', NULL, 1),
(6183917, 912070, 76335, '<td valign="top">An ephemeral moment nicely captured.</td>', 'An ephemeral moment nicely captured.', '2010-10-06 20:18:40.000000', NULL, 1),
(6183918, 910886, 76335, '<td valign="top">Nice study in color and texture.</td>', 'Nice study in color and texture.', '2010-10-06 20:19:07.000000', NULL, 1),
(6183933, 911765, 10785, '<td valign="top">Did a good job with the flash here. The lighting is still a little flat, but it''s not overly flat and the shadows are barely there. Some color and a better background would amp this up a lot!</td>', 'Did a good job with the flash here. The lighting is still a little flat, but it''s not overly flat and the shadows are barely there. Some color and a better background would amp this up a lot!', '2010-10-06 20:29:43.000000', NULL, 1),
(6183935, 911143, 10785, '<td valign="top">It''s cute and works to show off your lens skills!</td>', 'It''s cute and works to show off your lens skills!', '2010-10-06 20:30:31.000000', NULL, 1),
(6183938, 910952, 10785, '<td valign="top">Awesome capture! Great lighting. Looks like you really worked that sky in post. Love the dog''s color. The pop of white really stands out well!</td>', 'Awesome capture! Great lighting. Looks like you really worked that sky in post. Love the dog''s color. The pop of white really stands out well!', '2010-10-06 20:31:52.000000', NULL, 1),
(6183939, 912021, 10785, '<td valign="top">Awesome horizontal lines! The shell of the plane works as a slight diagonal. Even though the fields horizon is approximately centered, it still works. The gritty B&amp;W is very good with the subject here.</td>', 'Awesome horizontal lines! The shell of the plane works as a slight diagonal. Even though the fields horizon is approximately centered, it still works. The gritty B&W is very good with the subject here.', '2010-10-06 20:33:43.000000', NULL, 1),
(6183940, 910919, 10785, '<td valign="top">Looks like the butterfly is a little overexposed. The foliage is exposed well. Good focus and very crisp sharpness!</td>', 'Looks like the butterfly is a little overexposed. The foliage is exposed well. Good focus and very crisp sharpness!', '2010-10-06 20:34:38.000000', NULL, 1),
(6183941, 912112, 10785, '<td valign="top">Very cute. I am thinking this baby is about 1 year + or -. That is a difficult time to get a good shot because they aren''t standing still. Especially if they are walking! The car seat is nicely hidden.</td>', 'Very cute. I am thinking this baby is about 1 year + or -. That is a difficult time to get a good shot because they aren''t standing still. Especially if they are walking! The car seat is nicely hidden.', '2010-10-06 20:36:42.000000', NULL, 1),
(6183943, 912008, 10785, '<td valign="top">This has such great dimension to it it is almost 3D!</td>', 'This has such great dimension to it it is almost 3D!', '2010-10-06 20:38:37.000000', NULL, 1),
(6183947, 912018, 10785, '<td valign="top">The shot is very sharp and the exposure is spot on but Fall is just turning here... not too much color showing. The border is a little odd...</td>', 'The shot is very sharp and the exposure is spot on but Fall is just turning here... not too much color showing. The border is a little odd...', '2010-10-06 20:46:38.000000', NULL, 1),
(6183948, 911524, 10785, '<td valign="top">Great hairlight... but turned away??? Interesting choice for pose.</td>', 'Great hairlight... but turned away??? Interesting choice for pose.', '2010-10-06 20:48:03.000000', NULL, 1),
(6183974, 909230, 32145, '<td valign="top">Simple and powerful image.</td>', 'Simple and powerful image.', '2010-10-06 21:33:43.000000', NULL, 1),
(6183976, 907928, 32145, '<td valign="top">Great viewpoint and contrast in textures between the clouds and structure</td>', 'Great viewpoint and contrast in textures between the clouds and structure', '2010-10-06 21:37:32.000000', NULL, 1),
(6183981, 912226, 17722, '<td valign="top">This is what I want to do with my photography.</td>', 'This is what I want to do with my photography.', '2010-10-06 21:47:41.000000', NULL, 1),
(6183988, 909414, 70293, '<td valign="top">This pic could be a post card...very nice</td>', 'This pic could be a post card...very nice', '2010-10-06 21:52:57.000000', NULL, 1),
(6183989, 911992, 70293, '<td valign="top">Simply Beautiful!</td>', 'Simply Beautiful!', '2010-10-06 21:53:24.000000', NULL, 1),
(6184006, 908386, 70293, '<td valign="top">Wow</td>', 'Wow', '2010-10-06 22:04:19.000000', NULL, 1),
(6184007, 912073, 99710, '<td valign="top">instant favorite! 10</td>', 'instant favorite! 10', '2010-10-06 22:04:24.000000', NULL, 1),
(6184009, 911909, 99710, '<td valign="top">astonishing view, perfectly processed.</td>', 'astonishing view, perfectly processed.', '2010-10-06 22:05:22.000000', NULL, 1),
(6184030, 911524, 65234, '<td valign="top">Beautiful light and bokeh.  Pose makes me wonder what she''s looking at; I imagine I see a hint of a smile on her face.</td>', 'Beautiful light and bokeh.  Pose makes me wonder what she''s looking at; I imagine I see a hint of a smile on her face.', '2010-10-06 22:24:05.000000', NULL, 1),
(6184034, 910857, 65234, '<td valign="top">In the rain!  Not that the moose seems to care.  Like your composition and the colors in the field.</td>', 'In the rain!  Not that the moose seems to care.  Like your composition and the colors in the field.', '2010-10-06 22:24:52.000000', NULL, 1),
(6184045, 907785, 65234, '<td valign="top">Oh, yeah.  Great light; it would be lovely even in black and white, though obviously the mood wouldn''t be as warm.</td>', 'Oh, yeah.  Great light; it would be lovely even in black and white, though obviously the mood wouldn''t be as warm.', '2010-10-06 22:29:39.000000', NULL, 1),
(6184046, 911042, 65234, '<td valign="top">Gotta'' love those eyeballs ;-)</td>', 'Gotta'' love those eyeballs ;-)', '2010-10-06 22:30:11.000000', NULL, 1),
(6184047, 912226, 65234, '<td valign="top">Nicely moody with that fog.</td>', 'Nicely moody with that fog.', '2010-10-06 22:31:17.000000', NULL, 1),
(6184187, 909230, 73056, '<td valign="top">An awesome low key shot! Great subject, spot on lighting and perfect processing. For me, this is my blue. Good luck!</td>', 'An awesome low key shot! Great subject, spot on lighting and perfect processing. For me, this is my blue. Good luck!', '2010-10-07 02:48:18.000000', NULL, 1),
(6184336, 911141, 103142, '<td valign="top">I really like this shot. Nice job of seeing something intriguing in something most people would pass by.</td>', 'I really like this shot. Nice job of seeing something intriguing in something most people would pass by.', '2010-10-07 07:31:02.000000', NULL, 1),
(6184342, 908238, 103142, '<td valign="top">Very nice shot. I wish it was larger so I could really explore it. (doesn''t make a difference in the vote -- just wish it was the 800 pixel) -7-</td>', 'Very nice shot. I wish it was larger so I could really explore it. (doesn''t make a difference in the vote -- just wish it was the 800 pixel) -7-', '2010-10-07 07:34:43.000000', NULL, 1),
(6184352, 910122, 103142, '<td valign="top">Are both his eyes really that disgustingly large? How bizarre!</td>', 'Are both his eyes really that disgustingly large? How bizarre!', '2010-10-07 07:44:05.000000', NULL, 1),
(6184354, 911497, 103142, '<td valign="top">Very nice lines -- well seen and captured.</td>', 'Very nice lines -- well seen and captured.', '2010-10-07 07:44:38.000000', NULL, 1),
(6184356, 912095, 103142, '<td valign="top">I would love to see what this one looks like in color -- but the b&amp;w does capture the drama.</td>', 'I would love to see what this one looks like in color -- but the b&w does capture the drama.', '2010-10-07 07:47:55.000000', NULL, 1),
(6184358, 912106, 103142, '<td valign="top">great use of negative space -- it really adds to the feeling of being closed in.</td>', 'great use of negative space -- it really adds to the feeling of being closed in.', '2010-10-07 07:54:03.000000', NULL, 1),
(6184362, 911872, 103142, '<td valign="top">It''s an intriguing photo, but I wish he would have been more towards the right than centered. This has a dynamic feel to it, but centering seems to make it more static. I''m not saying it well, but it just doesn''t feel right here. -6-</td>', 'It''s an intriguing photo, but I wish he would have been more towards the right than centered. This has a dynamic feel to it, but centering seems to make it more static. I''m not saying it well, but it just doesn''t feel right here. -6-', '2010-10-07 07:57:31.000000', NULL, 1),
(6184367, 907690, 103142, '<td valign="top">Wonderful shot! I enjoyed it very much!</td>', 'Wonderful shot! I enjoyed it very much!', '2010-10-07 08:01:06.000000', NULL, 1),
(6184372, 909088, 103142, '<td valign="top">I really love the idea on this shot, and the people are great. But the lighting is a bit flat, a tad dark, and the color is problematic (your whites are baby blue instead of white.)<br/> <br/>Fun possibilities, but needs a bit more work.</td>', 'I really love the idea on this shot, and the people are great. But the lighting is a bit flat, a tad dark, and the color is problematic (your whites are baby blue instead of white.) Fun possibilities, but needs a bit more work.', '2010-10-07 08:06:58.000000', NULL, 1),
(6184373, 912044, 103142, '<td valign="top">Nice spot. Your horizon looks a bit tilted...</td>', 'Nice spot. Your horizon looks a bit tilted...', '2010-10-07 08:07:35.000000', NULL, 1),
(6184391, 911909, 110876, '<td valign="top">Realy nice picture.  The center (where my eye is drawn) looks a bit hazy.</td>', 'Realy nice picture.  The center (where my eye is drawn) looks a bit hazy.', '2010-10-07 08:43:28.000000', NULL, 1),
(6184395, 912150, 110876, '<td valign="top">I think I would like this better if it were brighter and the camera was tilted down a little to get more of the sand close up at the bottom.</td>', 'I think I would like this better if it were brighter and the camera was tilted down a little to get more of the sand close up at the bottom.', '2010-10-07 08:45:21.000000', NULL, 1),
(6184398, 909783, 110876, '<td valign="top">The forground could be brighter.</td>', 'The forground could be brighter.', '2010-10-07 08:46:32.000000', NULL, 1),
(6184406, 908129, 110876, '<td valign="top">I guess the baricades make some kind of statement.  It may have been a generally better picture a few steps forward to shoot around them though.</td>', 'I guess the baricades make some kind of statement.  It may have been a generally better picture a few steps forward to shoot around them though.', '2010-10-07 08:55:25.000000', NULL, 1),
(6184412, 912166, 70661, '<td valign="top">This is so cool! Going into my fav''s!</td>', 'This is so cool! Going into my fav''s!', '2010-10-07 09:10:22.000000', NULL, 1),
(6184417, 912111, 70661, '<td valign="top">I like this. I think it would have been better if you had cloned out the thing poking in on the left and the thing hanging down from the top.</td>', 'I like this. I think it would have been better if you had cloned out the thing poking in on the left and the thing hanging down from the top.', '2010-10-07 09:15:10.000000', NULL, 1),
(6184461, 912112, 114225, '<td valign="top">Cute photo. I''m not sure how I feel about the processing. It''s a bit artistic, but at the same time makes the whole thing a bit too soft for my taste.</td>', 'Cute photo. I''m not sure how I feel about the processing. It''s a bit artistic, but at the same time makes the whole thing a bit too soft for my taste.', '2010-10-07 10:29:20.000000', NULL, 1),
(6184462, 912146, 114225, '<td valign="top">Very good use of leading lines, color, and details.</td>', 'Very good use of leading lines, color, and details.', '2010-10-07 10:29:58.000000', NULL, 1),
(6184464, 909876, 114225, '<td valign="top">I''m torn on the softness of this photo. In one aspect, I like it, because it''s a more dreamy feel. But at the same time, it actually feels more like an accident than intentional.</td>', 'I''m torn on the softness of this photo. In one aspect, I like it, because it''s a more dreamy feel. But at the same time, it actually feels more like an accident than intentional.', '2010-10-07 10:30:42.000000', NULL, 1),
(6184467, 911332, 114225, '<td valign="top">Good choice of B&amp;W. I really like the idea of the veil blowing around. I''m not super keen on the position on the groom (so far back).</td>', 'Good choice of B&W. I really like the idea of the veil blowing around. I''m not super keen on the position on the groom (so far back).', '2010-10-07 10:33:40.000000', NULL, 1),
