(6184572, 912120, 114225, '<td valign="top">Great details in this photo. That stare is a bit spooky, but super cool.</td>', 'Great details in this photo. That stare is a bit spooky, but super cool.', '2010-10-07 11:56:03.000000', NULL, 1),
(6184574, 909961, 114225, '<td valign="top">I like the colors and composition used for this photo. I do wish there was a bit more light on the left side of the face. At least on my monitor, I''m seeing a reflection in the eyeball, but not the details, which is a bit distracting to me.</td>', 'I like the colors and composition used for this photo. I do wish there was a bit more light on the left side of the face. At least on my monitor, I''m seeing a reflection in the eyeball, but not the details, which is a bit distracting to me.', '2010-10-07 11:57:15.000000', NULL, 1),
(6184577, 911141, 114225, '<td valign="top">I very much like your use of depth of field on this photo. The choice of B&amp;W was a good one, as well as the composition.</td>', 'I very much like your use of depth of field on this photo. The choice of B&W was a good one, as well as the composition.', '2010-10-07 11:58:07.000000', NULL, 1),
(6184578, 910906, 114225, '<td valign="top">Nice colors and overall scenery. It feels that the overall sharpness of this photo is pretty soft, and there is a lot of color banding in the sky which are both taking a bit away from this photo.</td>', 'Nice colors and overall scenery. It feels that the overall sharpness of this photo is pretty soft, and there is a lot of color banding in the sky which are both taking a bit away from this photo.', '2010-10-07 11:59:06.000000', NULL, 1),
(6184579, 912192, 114225, '<td valign="top">Very cool abstract here. Good colors and nice tight crop.</td>', 'Very cool abstract here. Good colors and nice tight crop.', '2010-10-07 11:59:31.000000', NULL, 1),
(6184581, 912227, 114225, '<td valign="top">Great splash of color in this scene. I like the composition for the most part, but I think I may have chosen to crop out some of the sand.</td>', 'Great splash of color in this scene. I like the composition for the most part, but I think I may have chosen to crop out some of the sand.', '2010-10-07 12:00:43.000000', NULL, 1),
(6184589, 909705, 103142, '<td valign="top">I do love upside down images, yet so few work well. This one works nicely. Good choice on the processing.</td>', 'I do love upside down images, yet so few work well. This one works nicely. Good choice on the processing.', '2010-10-07 12:17:12.000000', NULL, 1),
(6184607, 911871, 103142, '<td valign="top">awesome shadow!! What a great find/capture! I would love to see what this looked like with a little more contrast. It seems edgy and dramatic -- but the processing doesn''t seem to quite match up with it. -8-</td>', 'awesome shadow!! What a great find/capture! I would love to see what this looked like with a little more contrast. It seems edgy and dramatic -- but the processing doesn''t seem to quite match up with it. -8-', '2010-10-07 12:47:26.000000', NULL, 1),
(6184612, 908129, 114225, '<td valign="top">Edited: Sorry, my old comment didn''t make sense. My browser was acting up while voting, and put some comments on the wrong photos somehow. For this photo, I really like the perspective and colors. I feel it''s just slightly over-sharpened in my eye, but not too much to really take away from the photo.<br/><br/><i>Message edited by author 2010-10-08 08:19:35.</i></td>', 'Edited: Sorry, my old comment didn''t make sense. My browser was acting up while voting, and put some comments on the wrong photos somehow. For this photo, I really like the perspective and colors. I feel it''s just slightly over-sharpened in my eye, but not too much to really take away from the photo.', '2010-10-07 12:55:02.000000', '2010-10-08 09:19:35.000000', 1),
