(6184728, 912235, 103142, '<td valign="top">Beautifully done -- stunning picture! (did he survive the shot?) -9-</td>', 'Beautifully done -- stunning picture! (did he survive the shot?) -9-', '2010-10-07 14:04:45.000000', NULL, 1),
(6184729, 912111, 103142, '<td valign="top">I really enjoyed this shot! The background is just wonderful. I''d be tempted to clone out the hardware on the left and at the top. Though they''re a little bit intriguing, I think the draw the eye away from the main interest, and break up the serenity of the shot. What a great find! -9-</td>', 'I really enjoyed this shot! The background is just wonderful. I''d be tempted to clone out the hardware on the left and at the top. Though they''re a little bit intriguing, I think the draw the eye away from the main interest, and break up the serenity of the shot. What a great find! -9-', '2010-10-07 14:04:46.000000', NULL, 1),
(6184730, 909828, 103142, '<td valign="top">I think this is an incredibly cool shot. I hope it''s doing well for you. -8-</td>', 'I think this is an incredibly cool shot. I hope it''s doing well for you. -8-', '2010-10-07 14:04:49.000000', NULL, 1),
