(6185638, 910113, 100831, '<td valign="top">Geez that was noisy. (I''ll be back after I settle down).</td>', 'Geez that was noisy. (I''ll be back after I settle down).', '2010-10-08 00:22:21.000000', NULL, 1),
(6185639, 911584, 100831, '<td valign="top">and that''s not just ANY wheel!</td>', 'and that''s not just ANY wheel!', '2010-10-08 00:22:27.000000', NULL, 1),
